package io.github.diodeme.ji.remote;

/** CLI marker for the client-assisted SSH product. Product integrations call RemoteHostInstaller. */
public final class JiRemoteBootstrap {
    private JiRemoteBootstrap() {}

    public static void main(String[] args) {
        if (args.length == 0 || "--help".equals(args[0])) {
            System.out.println("usage: ji-remote install|tunnel (requires an explicit signed private bundle)");
            return;
        }
        throw new IllegalArgumentException("use the typed RemoteHostInstaller integration");
    }
}
